":"Paris","publication_year":"1997","edition_statement":null,"language":"fre","isbn":"2-7324-2351-3","issn":null,"subjects":["Fleurs"],"raw_payload":{"leader":"02348nam0 22002651i 450 ","fields":[{"tag":"001","value":"15"},{"tag":"100","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"20050101u        u  u0frey50  "}]},{"tag":"009","value":"  \u001fa1997-01-01\u001fc2005-01-01 00:00:00\u001fu2010-07-30 04:23:43"},{"tag":"200","ind1":"1","ind2":" ","subfields":[{"code":"a","value":"La métamorphose des fleurs"}]},{"tag":"010","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"2-7324-2351-3"}]},{"tag":"101","ind1":"0","ind2":" ","subfields":[{"code":"a","value":"fre"}]},{"tag":"215","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"143 p. dont 4 dépl."},{"code":"c","value":"ill. en coul., jaquette ill. en coul."},{"code":"d","value":"30 cm"}]},{"tag":"330","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Avec Microcosmos, des milliers de lecteurs se sont émerveillés devant les prodiges insoupçonnés d'un petit carré d'herbes folles. Dans la Métamorphose des Fleurs, Claude Nuridsany et Marie Pérennou sillonnent prairies et jardins et invitent nos yeux inattentifs à se poser sur un bouton gorgé de sève, un pétale qui s'entrouvre ou la chute d'une corolle. Autant de moments phares de la vie flamboyante d'une fleur, architecture de rêve construite et défaite en quelques jours. Transfigurées par la magie de la macrophotographie, une vingtaine d'espèces florales naissent, vivent et meurent sous nos yeux. Marie Pérennou et Claude Nuridsany ont inventé, pour notre plus grand plaisir, un nouveau regard sur la nature, à mi-chemin entre la biologie et la poésie."}]},{"tag":"319","ind1":" ","ind2":" ","subfields":[{"code":"a","value":"Aucun droit spécifique"}]},{"tag":"701","ind1":" ","ind2":"1","subfields":[{"code":"a","value":"Pérennou"},{"code":"b","value":"Marie"},{"code":"4","value":"007"},{"code":"f","value":"1946-...."},{"code":"9","value":"id:17"}]},