BEGIN
  -- ── Décor ───────────────────────────────────────────────────────────
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  INSERT INTO public.network_administrators (user_id, status) VALUES (v_admin, 'active');
  INSERT INTO public.catalog_ref_source_partners (code, label, sort_order, is_active)
  VALUES ('other_partner', 'Outro parceiro', 80, true) ON CONFLICT (code) DO NOTHING;
  UPDATE public.libraries SET tombo_pattern = '{"prefix": "L6B-T-", "year": false, "pad": 4}'::jsonb WHERE id = v_lib;
  INSERT INTO public.libraries (id, slug, name, is_active, visibility_level, tombo_pattern)
  VALUES (gen_random_uuid(), 'essai-h21-l6b-b', 'Essai H21 lot 6b — B', true, 'private',
          '{"prefix": "L6BB-T-", "year": false, "pad": 4}'::jsonb)
  RETURNING id INTO v_libB;
  UPDATE public.user_library_memberships SET status = 'inactive', is_primary = false WHERE user_id = v_coordB;
  INSERT INTO public.user_library_memberships (user_id, library_id, role, status, is_primary)
  VALUES (v_coordB, v_libB, 'coordenador', 'active', true);

  INSERT INTO ingest.partner_catalog_sources (partner_name, library_id, relation_status, source_kind, import_enabled)
  VALUES ('L6B PMB 8.1 (fixtures)', v_lib, 'mapeada', 'own_catalog', true) RETURNING id INTO v_src;

  -- Premier import : promu, révisé, publié.
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l6b-pmb.iso', 'l6b-pmb.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run1;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run1, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'new_record', 'accept_new'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  v_res := public.fn_import_promote(v_run1, ARRAY['new_record'], ARRAY['accept_new']);
  v_lot1 := (v_res->>'batch_id')::bigint;
  UPDATE public.book_drafts SET bib_ref = 'L6B-PMB-REF-' || id WHERE batch_id = v_lot1 AND bib_ref IS NULL;
  v_res := public.fn_batch_review_request(v_lot1);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
  PERFORM public.fn_batch_review_verdict((v_res->>'review_id')::bigint, 'approved', NULL);
  PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  PERFORM public.publish_catalog_batch(v_lot1);
  IF (SELECT count(*) FROM public.book_drafts WHERE batch_id = v_lot1 AND status = 'published') <> 64 THEN
    RAISE EXCEPTION 'decor : publication incomplete';
  END IF;
  SELECT max(e.id) FILTER (WHERE e.source_item_code = '33700004388761'), max(e.id) FILTER (WHERE e.source_item_code = '22020295067'),
         max(e.id) FILTER (WHERE e.source_item_code = '6438646236'), max(e.id) FILTER (WHERE e.source_item_code = '33700003413727'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003470461'), max(e.id) FILTER (WHERE e.source_item_code = '33700003719453'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003550072'), max(e.id) FILTER (WHERE e.source_item_code = '33700004389030'),
         max(e.id) FILTER (WHERE e.source_item_code = '33700003669484'), max(e.id) FILTER (WHERE e.source_item_code = '33700003669485')
    INTO e1, e2a, e2b, e3, e4, e5, e6, e7, e9, e10
    FROM public.exemplares e WHERE e.library_id = v_lib;
  SELECT max(h.book_id) FILTER (WHERE e.id = e1), max(h.book_id) FILTER (WHERE e.id = e2a), max(h.book_id) FILTER (WHERE e.id = e5)
    INTO b1, b2, b5
    FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id IN (e1, e2a, e5);

  -- ── T1 ──────────────────────────────────────────────────────────────
  v_t := 'T1 premiere publication : une base par exemplaire importe, valeurs du fichier, BLMF, confirmee';
  BEGIN
    IF (SELECT count(*) FROM ingest.exemplar_import_baselines bl JOIN public.exemplares e ON e.id = bl.exemplar_id
         WHERE e.import_run_id = v_run1) = 46
       AND NOT EXISTS (SELECT 1 FROM ingest.exemplar_import_baselines bl JOIN public.exemplares e ON e.id = bl.exemplar_id
                        WHERE e.import_run_id = v_run1
                          AND (bl.library_id IS DISTINCT FROM v_lib OR bl.origine <> 'import' OR bl.confirmed_at IS NULL
                               OR bl.run_id IS DISTINCT FROM v_run1 OR bl.source_id IS DISTINCT FROM v_src
                               OR bl.source_item_code IS DISTINCT FROM e.source_item_code
                               OR bl.shelf_location IS DISTINCT FROM e.shelf_location
                               OR bl.notes IS DISTINCT FROM e.notes))
       AND (SELECT bl.shelf_location FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e1) = 'JR SOU'
       AND EXISTS (SELECT 1 FROM ingest.exemplar_import_baselines bl WHERE bl.notes IS NOT NULL)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : bases '
         ||(SELECT count(*) FROM ingest.exemplar_import_baselines)); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── Le réimport : les mêmes lignes, cotes et notes retouchées ──────────
  INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
  VALUES (v_src, v_lib, 'essai/l6b-pmb-reimport.iso', 'l6b-pmb-reimport.iso', 'marc_iso2709', 'parsed') RETURNING id INTO v_run2;
  INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, item_type, title, subtitle, responsibility_statement, authors, publisher, place_of_publication, publication_year, edition_statement, language, isbn, issn, subjects, raw_payload, normalized_payload, match_status, editorial_decision)
  SELECT v_run2, r.row_no, r.external_key, r.item_type, r.title, r.subtitle, r.responsibility_statement, r.authors, r.publisher, r.place_of_publication, r.publication_year, r.edition_statement, r.language, r.isbn, r.issn, r.subjects, r.raw_payload, r.normalized_payload, 'unreviewed', 'pending'
    FROM jsonb_to_recordset(v_pmb)
      AS r(row_no integer, external_key text, item_type text, title text, subtitle text, responsibility_statement text, authors jsonb, publisher text, place_of_publication text, publication_year text, edition_statement text, language text, isbn text, issn text, subjects jsonb, raw_payload jsonb, normalized_payload jsonb);
  SELECT max(id) FILTER (WHERE row_no = 1), max(id) FILTER (WHERE row_no = 2), max(id) FILTER (WHERE row_no = 3),
         max(id) FILTER (WHERE row_no = 4), max(id) FILTER (WHERE row_no = 5), max(id) FILTER (WHERE row_no = 6),
         max(id) FILTER (WHERE row_no = 7), max(id) FILTER (WHERE row_no = 9), max(id) FILTER (WHERE row_no = 10)
    INTO r1, r2, r3, r4, r5, r6, r7, r9, r10
    FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2;
  SELECT sr.id INTO rN FROM ingest.partner_catalog_staging_rows sr
   WHERE sr.run_id = v_run2 AND sr.row_no > 11 AND jsonb_array_length(sr.normalized_payload->'items') = 1
     AND nullif(btrim(sr.normalized_payload->'items'->0->>'note'), '') IS NOT NULL
   ORDER BY sr.row_no LIMIT 1;
  SELECT e.id, h.book_id INTO eN, bN
    FROM ingest.partner_catalog_staging_rows sr
    JOIN public.exemplares e ON e.library_id = v_lib AND e.source_item_code = sr.normalized_payload->'items'->0->>'source_item_code'
    JOIN public.book_holdings h ON h.id = e.holding_id
   WHERE sr.id = rN;
  IF rN IS NULL OR eN IS NULL OR e1 IS NULL OR e2b IS NULL OR e10 IS NULL OR b5 IS NULL THEN
    RAISE EXCEPTION 'decor : fixture inattendue (rN %, eN %)', rN, eN;
  END IF;
  -- dans le fichier
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"JR SOU 2"') WHERE id = r1;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,1,call_number}', '"R HER N"') WHERE id = r2;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,note}', '"L6B note nouvelle"') WHERE id = r3;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', 'null') WHERE id = r4;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"JR CAU 5"'),
         publication_year = '2015' WHERE id = r5;
  -- l'exemplaire du rang 4 passe, dans PMB, sous la notice du rang 5 : déplacé
  UPDATE ingest.partner_catalog_staging_rows
     SET normalized_payload = jsonb_set(normalized_payload, '{items}', (normalized_payload->'items')
           || '[{"source_item_code": "33700003470461", "source_item_id": "4", "call_number": "R ZIM"}]'::jsonb)
   WHERE id = r5;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"L6B SANS BASE"') WHERE id = r6;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"L6B EDITER"') WHERE id = r7;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"ID PAREIL"') WHERE id = r9;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', '"L6B REJET"') WHERE id = r10;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,note}',
           to_jsonb((normalized_payload->'items'->0->>'note') || ' (revue)')),
         publication_year = '1999' WHERE id = rN;
  UPDATE ingest.partner_catalog_staging_rows SET normalized_payload = jsonb_set(normalized_payload, '{items,0,call_number}', 'null') WHERE id = rN;
  v_coteN := (SELECT shelf_location FROM public.exemplares WHERE id = eN);
  IF v_coteN IS NULL THEN RAISE EXCEPTION 'decor : la cote de l''exemplaire de rN est vide'; END IF;
  -- dans AnarBib
  UPDATE public.exemplares SET shelf_location = 'JR HER LOCAL' WHERE id = e2a;
  UPDATE public.exemplares SET shelf_location = 'R HER A' WHERE id = e2b;
  UPDATE public.exemplares SET shelf_location = 'ID PAREIL' WHERE id = e9;
  UPDATE public.exemplares SET shelf_location = 'ER OPP LOCAL' WHERE id = e3;
  -- l'exemplaire du rang 1 porte une étiquette, une date d'acquisition : la copie
  -- doit les reprendre (« une colonne = tous les endroits »)
  UPDATE public.exemplares SET label_note = 'L6B etiquette initiale', label_cdd_override = '320',
         acquisition_date = DATE '2020-01-02' WHERE id = e1;
  DELETE FROM ingest.exemplar_import_baselines WHERE exemplar_id = e6;
  -- la notice du rang 5 partagée : B y a un fonds et un exemplaire
  INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (b5, v_libB, true);
  INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, shelf_location, notes, source_item_code, circulation_policy)
  SELECT b.bib_ref, 'L6BB-X-1', v_libB, h.id, 'JR CAU', 'exemplaire de B', '33700003719453', 'ambos'
    FROM public.books b JOIN public.book_holdings h ON h.book_id = b.id AND h.library_id = v_libB WHERE b.id = b5
  RETURNING id INTO eB;
  -- l'exemplaire du rang 1 est prêté et réservé
  INSERT INTO public.emprestimos_v2 (user_id, library_id, status_global, due_at)
  VALUES (v_lect, v_lib, 'aberto', current_date + 30) RETURNING id INTO v_emp;
  INSERT INTO public.emprestimo_itens_v2 (emprestimo_id, line_no, sub_id, book_id, item_id, holding_id, bib_ref, due_at)
  SELECT v_emp, 1, v_emp || '.1', b1, e1, e.holding_id, e.bib_ref, current_date + 30 FROM public.exemplares e WHERE e.id = e1;
  INSERT INTO public.reservas_v2 (user_id, library_id, status_global) VALUES (v_admin, v_lib, 'ativa') RETURNING id INTO v_resv;
  INSERT INTO public.reserva_linhas_v2 (reserva_id, line_no, book_id, item_id, holding_id, bib_ref)
  SELECT v_resv, 1, b1, e1, e.holding_id, e.bib_ref FROM public.exemplares e WHERE e.id = e1;
  -- (le circuit de prêt recalcule la disponibilité du fonds ; ici, à la main)
  PERFORM public.fn_v2_recompute_holdings_availability(p_holding_ids := ARRAY[(SELECT e.holding_id FROM public.exemplares e WHERE e.id = e1)]);
  -- un « Éditer » en cours sur l'exemplaire du rang 7
  dEdit := public.create_exemplar_draft_from_exemplar(e7, NULL);
  PERFORM ingest.fn_match_partner_catalog_run(v_run2);
  IF (SELECT count(*) FROM ingest.partner_catalog_staging_rows WHERE run_id = v_run2 AND match_status = 'known_record') <> 64 THEN
    RAISE EXCEPTION 'decor : reimport non reconnu';
  END IF;
  -- la ligne du rang 10 rejetée par choix
  EXECUTE 'SET LOCAL ROLE authenticated';
  PERFORM public.fn_import_set_editorial(v_run2, ARRAY[r10], 'reject', 'page import: écarté');
  EXECUTE 'RESET ROLE';

  -- Empreintes : le catalogue entier ; l'exemplaire hors cote et note ; sa
  -- circulation ; son fonds (comptes compris) ; l'exemplaire de B.
  v_ref := 'select md5(concat_ws(''|'',
      (select string_agg(md5(to_jsonb(b)::text), '','' order by b.id) from public.books b),
      (select string_agg(md5(to_jsonb(h)::text), '','' order by h.id) from public.book_holdings h),
      (select string_agg(md5(to_jsonb(e)::text), '','' order by e.id) from public.exemplares e),
      (select string_agg(md5(to_jsonb(x)::text), '','' order by x.id) from public.book_external_ids x),
      (select string_agg(md5(to_jsonb(bl)::text), '','' order by bl.id) from ingest.exemplar_import_baselines bl),
      (select string_agg(md5(to_jsonb(i)::text), '','' order by i.id) from public.emprestimo_itens_v2 i),
      (select string_agg(md5(to_jsonb(l)::text), '','' order by l.id) from public.reserva_linhas_v2 l)))';
  v_circ := md5(concat_ws('|',
      (SELECT string_agg(md5(to_jsonb(i)::text), ',' ORDER BY i.id) FROM public.emprestimo_itens_v2 i WHERE i.item_id = e1),
      (SELECT string_agg(md5(to_jsonb(l)::text), ',' ORDER BY l.id) FROM public.reserva_linhas_v2 l WHERE l.item_id = e1),
      (SELECT string_agg(md5(to_jsonb(p)::text), ',' ORDER BY p.id) FROM public.emprestimos_v2 p WHERE p.id = v_emp)));
  v_hold := (SELECT md5((to_jsonb(h) - 'updated_at')::text) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e1);
  v_ebB := (SELECT md5(to_jsonb(e)::text) FROM public.exemplares e WHERE e.id = eB);
  v_hp1 := (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = e1);
  v_hpN := (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = eN);
  v_hp5 := (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = e5);

  -- ── T2 ──────────────────────────────────────────────────────────────
  v_t := 'T2 recalcul : verdicts (source_seule, local_seul, conflit, identique, inchange, videe, sans_base) ; aucune ecriture ; liste ; detail';
  DECLARE v_l jsonb; v_d jsonb;
  BEGIN
    EXECUTE v_ref INTO v_avant;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_recomparer(v_run2, NULL);
    SELECT jsonb_object_agg(l.id::text, coalesce(l.exemplaires_maj, 'null'::jsonb)) INTO v_l
      FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id IN (r1, r2, r3, r4, r5, r6, r7, r9, r10, rN);
    v_d := public.fn_import_row_comparison(v_run2, r2);
    EXECUTE 'RESET ROLE';
    EXECUTE v_ref INTO v_apres;
    IF v_apres = v_avant
       AND (v_res->>'exemplaires_comparees')::int = 64
       AND v_l->(r1::text)->'items'->0->'verdicts' = '{"shelf_location": "source_seule", "notes": "inchange"}'::jsonb
       AND (v_l->(r1::text)->>'applicables')::int = 1
       AND v_l->(r2::text)->'items'->0->'verdicts' = '{"shelf_location": "local_seul", "notes": "inchange"}'::jsonb
       AND v_l->(r2::text)->'items'->1->'verdicts' = '{"shelf_location": "conflit", "notes": "inchange"}'::jsonb
       AND (v_l->(r2::text)->>'applicables')::int = 0
       AND v_l->(r9::text)->'items'->0->'verdicts'->>'shelf_location' = 'identique'
       AND v_l->(r3::text)->'items'->0->'verdicts' = '{"shelf_location": "local_seul", "notes": "source_seule"}'::jsonb
       AND v_l->(rN::text)->'items'->0->'verdicts'->>'shelf_location' = 'source_seule'
       AND v_l->(r5::text)->'items'->1->>'constat' = 'deplace'
       AND v_l->(r4::text)->'items'->0->'verdicts'->>'shelf_location' = 'source_seule'
       AND (v_l->(r4::text)->>'applicables')::int = 0          -- vidée : jamais appliquée
       AND v_l->(r6::text)->'items'->0->'verdicts'->>'shelf_location' = 'sans_base'
       AND (v_l->(r7::text)->>'applicables')::int = 0
       AND v_l->(r7::text)->'items'->0->>'empeche' = 'brouillon_en_cours'
       AND (v_l->(r6::text)->'items'->0->>'sans_base')::boolean
       AND (v_l->(r10::text)->>'applicables')::int = 0         -- rejetée par choix
       AND (v_l->(r5::text)->>'applicables')::int = 1
       AND (v_l->(rN::text)->>'applicables')::int = 1
       -- la liste ne porte aucune valeur
       AND NOT (v_l->(r2::text)->'items'->0 ? 'champs')
       -- le détail : base, AnarBib, fichier
       AND (SELECT c FROM jsonb_array_elements(v_d->'exemplaires'->'items'->1->'champs') c WHERE c->>'champ' = 'shelf_location')
           = '{"champ": "shelf_location", "verdict": "conflit", "b": "R HER", "a": "R HER A", "n": "R HER N"}'::jsonb
       AND (v_d->'exemplaires'->'items'->1->>'a_masque')::boolean = false
       AND NOT (v_d->'exemplaires'->'items'->1 ? 'empreinte_exemplaire')
       AND (v_d->'exemplaires'->'items'->1->>'exemplar_id')::bigint = e2b
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : catalogue '||CASE WHEN v_apres = v_avant THEN 'intact' ELSE 'CHANGE' END
         ||' res='||left(coalesce((v_res - 'rows')::text, 'NULL'), 200)||' liste='||left(coalesce(v_l::text, 'NULL'), 900)
         ||' detail='||left(coalesce((v_d->'exemplaires')::text, 'NULL'), 400)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T2b ─────────────────────────────────────────────────────────────
  v_t := 'T2b une base posee pour une autre bibliotheque n''est pas utilisable : sans_base (annule ensuite)';
  DECLARE v_v text; v_bid text;
  BEGIN
    BEGIN
      UPDATE ingest.exemplar_import_baselines SET library_id = v_libB WHERE exemplar_id = e10;
      SELECT c->>'verdict', x->>'baseline_id' INTO v_v, v_bid
        FROM jsonb_array_elements(ingest.fn_h21_exemplaires_trois_etats(r10)->'items') x
        CROSS JOIN LATERAL jsonb_array_elements(x->'champs') c
       WHERE c->>'champ' = 'shelf_location';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_v = 'sans_base' AND v_bid IS NULL
       AND (SELECT c->>'verdict' FROM jsonb_array_elements(ingest.fn_h21_exemplaires_trois_etats(r10)->'items') x
              CROSS JOIN LATERAL jsonb_array_elements(x->'champs') c WHERE c->>'champ' = 'shelf_location') = 'source_seule'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_v, '∅')||' / '||coalesce(v_bid, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T3 ──────────────────────────────────────────────────────────────
  v_t := 'T3 preparer : brouillons des seuls preparables, raisons des autres, lot ouvert du run, copie complete patchee, trace ; notice partagee ignoree, son exemplaire prepare';
  DECLARE v_x public.exemplar_drafts%rowtype; v_e public.exemplares%rowtype; v_u jsonb;
  BEGIN
    EXECUTE v_ref INTO v_avant;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r1, r2, r3, r4, r5, r6, r7, r9, r10, rN]);
    EXECUTE 'RESET ROLE';
    v_lotX := (v_res->>'batch_id')::bigint;
    SELECT x.id INTO d1 FROM public.exemplar_drafts x WHERE x.published_exemplar_id = e1 AND x.import_update IS NOT NULL;
    SELECT x.id INTO d3 FROM public.exemplar_drafts x WHERE x.published_exemplar_id = e3 AND x.import_update IS NOT NULL;
    SELECT x.id INTO d5 FROM public.exemplar_drafts x WHERE x.published_exemplar_id = e5 AND x.import_update IS NOT NULL;
    SELECT x.id INTO dN FROM public.exemplar_drafts x WHERE x.published_exemplar_id = eN AND x.import_update IS NOT NULL;
    SELECT m.draft_id INTO dNotice FROM ingest.partner_catalog_row_to_draft m WHERE m.staging_row_id = rN;
    SELECT * INTO v_x FROM public.exemplar_drafts WHERE id = d1;
    SELECT * INTO v_e FROM public.exemplares WHERE id = e1;
    v_u := v_x.import_update;
    IF (v_res->'exemplaires'->>'prepared')::int = 4
       AND v_res->'exemplaires'->'skipped' = '{"rien_a_appliquer": 5, "sans_base": 1, "brouillon_en_cours": 1, "rejetee": 1, "signale": 1}'::jsonb
       -- la notice : rN préparée (seule détentrice), r5 partagée
       AND (v_res->>'prepared')::int = 1 AND (v_res->'skipped'->>'partagee')::int = 1
       AND dNotice IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM ingest.partner_catalog_row_to_draft m WHERE m.staging_row_id = r5)
       AND d1 IS NOT NULL AND d3 IS NOT NULL AND d5 IS NOT NULL AND dN IS NOT NULL
       -- le lot ouvert du run, né d'un import, de BLMF
       AND (SELECT count(DISTINCT x.batch_id) FROM public.exemplar_drafts x WHERE x.id IN (d1, d3, d5, dN)) = 1
       AND v_x.batch_id = v_lotX AND (SELECT batch_id FROM public.book_drafts WHERE id = dNotice) = v_lotX
       AND public.fn_batch_is_imported(v_lotX)
       AND (SELECT library_id FROM public.catalog_batches WHERE id = v_lotX) = v_lib
       -- la copie complète, patchée de la seule cote
       AND v_x.action = 'update' AND v_x.status = 'draft' AND NOT coalesce(v_x.retake_untouched, false)
       AND v_x.import_staging_row_id = r1 AND v_x.book_draft_id IS NULL
       AND v_x.shelf_location = 'JR SOU 2' AND v_x.notes IS NOT DISTINCT FROM v_e.notes
       AND v_x.tombo = v_e.tombo AND v_x.target_library_id = v_e.library_id AND v_x.target_holding_id = v_e.holding_id
       AND v_x.target_bib_ref = v_e.bib_ref
       AND v_x.label_title_override IS NOT DISTINCT FROM v_e.label_title_override
       AND v_x.label_author_override IS NOT DISTINCT FROM v_e.label_author_override
       AND v_x.label_cdd_override IS NOT DISTINCT FROM v_e.label_cdd_override
       AND v_x.label_note IS NOT DISTINCT FROM v_e.label_note
       AND v_x.acquisition_mode IS NOT DISTINCT FROM v_e.acquisition_mode
       AND v_x.acquisition_date IS NOT DISTINCT FROM v_e.acquisition_date
       AND v_x.provenance_note IS NOT DISTINCT FROM v_e.provenance_note
       AND v_x.source_library IS NOT DISTINCT FROM v_e.source_library
       AND v_x.circulation_policy IS NOT DISTINCT FROM v_e.circulation_policy
       AND v_x.visibility IS NOT DISTINCT FROM v_e.visibility
       AND v_x.source_item_code = v_e.source_item_code AND v_x.source_item_id = v_e.source_item_id
       AND v_x.import_source_id = v_e.import_source_id AND v_x.import_run_id = v_run1
       -- la trace
       AND (v_u->>'exemplar_id')::bigint = e1 AND (v_u->>'staging_row_id')::bigint = r1 AND (v_u->>'run_id')::bigint = v_run2
       AND (v_u->>'book_id')::bigint = b1 AND v_u->>'library_id' = v_lib::text
       AND v_u->'appliques' = '[{"champ": "shelf_location", "b": "JR SOU", "a": "JR SOU", "n": "JR SOU 2"}]'::jsonb
       AND v_u->'montres' = '[]'::jsonb
       AND v_u->>'empreinte_exemplaire' = ingest.fn_h21_empreinte_exemplaire(e1)
       AND v_u->>'empreinte_base' = ingest.fn_h21_empreinte_base_exemplaire((v_u->>'baseline_id')::bigint)
       -- la note ajoutée (r3) appliquée, la cote gardée
       -- … la cote changée dans AnarBib seulement gardée (montrée, local_seul)
       AND (SELECT x.notes = 'L6B note nouvelle' AND x.shelf_location = 'ER OPP LOCAL' FROM public.exemplar_drafts x WHERE x.id = d3)
       AND (SELECT x.import_update->'montres' @> '[{"champ": "shelf_location", "verdict": "local_seul"}]'::jsonb FROM public.exemplar_drafts x WHERE x.id = d3)
       -- rN : la note appliquée, la cote vidée par le fichier montrée, jamais vidée
       AND (SELECT x.shelf_location = v_coteN AND x.notes LIKE '% (revue)'
                   AND x.import_update->'montres' @> '[{"champ": "shelf_location", "raison": "efface_par_la_source"}]'::jsonb
              FROM public.exemplar_drafts x WHERE x.id = dN)
       -- aucune écriture au catalogue (hors brouillons)
       AND (SELECT count(*) FROM public.exemplar_drafts x WHERE x.import_update IS NOT NULL) = 4
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_res::text, 'NULL'), 900)
         ||' trace='||left(coalesce(v_u::text, 'NULL'), 600)); END IF;
    EXECUTE v_ref INTO v_apres;
    IF v_apres <> v_avant THEN
      v_failed := v_failed+1; v_failures := v_failures||(v_t||' : le catalogue a change');
    END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4 ──────────────────────────────────────────────────────────────
  v_t := 'T4 deuxieme preparation : deja_preparee, aucun brouillon de plus';
  BEGIN
    v_nx := (SELECT count(*) FROM public.exemplar_drafts);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r1, r3, r5, rN]);
    EXECUTE 'RESET ROLE';
    IF (v_res->'exemplaires'->>'prepared')::int = 0 AND (v_res->'exemplaires'->'skipped'->>'deja_preparee')::int = 4
       AND (SELECT count(*) FROM public.exemplar_drafts) = v_nx
       -- la liste : plus rien à préparer, le brouillon est dit
       AND (SELECT (l.exemplaires_maj->>'applicables')::int = 0 AND (l.exemplaires_maj->'items'->0->>'draft_id')::bigint = d1
              FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id = r1)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_res::text, 'NULL'), 500)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T4b ─────────────────────────────────────────────────────────────
  v_t := 'T4b mise a jour vivante : Editer et brouillon de reprise API refuses ; liste d''un autre run sans preparable ; mise a jour supplantee refusee (corbeille, journal)';
  DECLARE v_h1 text; v_h2 text; v_h3 text; v_h4 text; v_run3 bigint; v_rr bigint; v_l jsonb; v_aud bigint; v_nouv bigint;
  BEGIN
    BEGIN
      -- (1) « Éditer » e1 pendant que d1 est vivant
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.create_exemplar_draft_from_exemplar(e1, NULL); v_h1 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
      -- (2) un brouillon de reprise posé directement par l'API
      BEGIN
        INSERT INTO public.exemplar_drafts (published_exemplar_id, action, status, label_status, target_library_id, target_bib_ref, shelf_location)
        SELECT e.id, 'update', 'draft', 'pending', e.library_id, e.bib_ref, 'API' FROM public.exemplares e WHERE e.id = e1;
        v_h2 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      -- (3) un autre run, la même ligne : rien de préparable (déjà préparé ailleurs)
      INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
      VALUES (v_src, v_lib, 'essai/l6b-bis.iso', 'l6b-bis.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_run3;
      INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
      SELECT v_run3, sr.row_no, sr.external_key, sr.title, sr.normalized_payload, 'known_record', 'pending', sr.proposed_book_id
        FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r1
      RETURNING id INTO v_rr;
      EXECUTE 'SET LOCAL ROLE authenticated';
      PERFORM public.fn_import_recomparer(v_run3, ARRAY[v_rr]);
      SELECT l.exemplaires_maj INTO v_l FROM public.fn_import_list_run_rows(v_run3) l WHERE l.id = v_rr;
      EXECUTE 'RESET ROLE';
      -- (4) d5 à la corbeille, la ligne re-préparée, d5 ne revient pas
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET status = 'cancelled' WHERE id = d5;
      v_res := public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r5]);
      BEGIN UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = d5; v_h3 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h3 = PG_EXCEPTION_HINT; END;
      -- (5) le nouveau supprimé, rejoué du journal pendant qu'un autre vit : refusé
      v_nouv := (SELECT x.id FROM public.exemplar_drafts x WHERE x.published_exemplar_id = e5 AND x.import_update IS NOT NULL AND x.status = 'draft');
      DELETE FROM public.exemplar_drafts WHERE id = v_nouv;
      EXECUTE 'RESET ROLE';
      v_aud := (SELECT max(a.id) FROM public.catalog_audit_log a WHERE a.action = 'delete' AND (a.details->'snapshot'->>'id')::bigint = v_nouv);
      UPDATE public.exemplar_drafts SET status = 'draft' WHERE id = d5;   -- (postgres : d5 revient, rien d'autre ne vit)
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.fn_restore_deleted_draft(v_aud); v_h4 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h4 = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_h1 = 'error.catalog.item_update_pending' AND v_h2 = 'error.catalog.item_update_pending'
       AND (v_l->>'applicables')::int = 0 AND v_l->'items'->0->>'empeche' = 'deja_preparee'
       AND (v_res->'exemplaires'->>'prepared')::int = 1
       AND v_h3 = 'error.import.item_update_superseded' AND v_h4 = 'error.import.item_update_superseded'
       AND v_aud IS NOT NULL
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2, v_h3, v_h4, coalesce(v_aud::text, 'audit ∅'))
         ||' liste='||left(coalesce(v_l::text, '∅'), 300)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T5 ──────────────────────────────────────────────────────────────
  v_t := 'T5 l''exemplaire de B, sur la notice partagee : jamais touche, aucun brouillon';
  BEGIN
    IF (SELECT md5(to_jsonb(e)::text) FROM public.exemplares e WHERE e.id = eB) = v_ebB
       AND NOT EXISTS (SELECT 1 FROM public.exemplar_drafts x WHERE x.published_exemplar_id = eB)
       AND NOT EXISTS (SELECT 1 FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = eB)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T6 ──────────────────────────────────────────────────────────────
  v_t := 'T6 l''API ne pose ni ne change la trace, ni l''exemplaire vise (INSERT et UPDATE)';
  DECLARE v_h1 text; v_h2 text; v_h3 text; v_h4 text;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN
      INSERT INTO public.exemplar_drafts (published_exemplar_id, action, status, label_status, target_library_id, target_bib_ref, import_update)
      VALUES (e2a, 'update', 'draft', 'pending', v_lib, 'x', '{"exemplar_id": 1}'::jsonb);
      v_h1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
    BEGIN
      UPDATE public.exemplar_drafts SET import_update = import_update || '{"empreinte_exemplaire": "x"}'::jsonb WHERE id = d1;
      v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
    BEGIN
      UPDATE public.exemplar_drafts SET import_update = NULL WHERE id = d1;
      v_h3 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h3 = PG_EXCEPTION_HINT; END;
    BEGIN
      UPDATE public.exemplar_drafts SET published_exemplar_id = e2a WHERE id = d1;
      v_h4 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h4 = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    IF v_h1 = 'error.import.item_update_trace_reserved' AND v_h2 = 'error.import.item_update_trace_reserved'
       AND v_h3 = 'error.import.item_update_trace_reserved' AND v_h4 = 'error.import.item_update_trace_reserved'
       AND (SELECT import_update IS NOT NULL AND published_exemplar_id = e1 FROM public.exemplar_drafts WHERE id = d1)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2, v_h3, v_h4)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T7 ──────────────────────────────────────────────────────────────
  v_t := 'T7 droits du geste : lectrice, librarian, autre bibliotheque refusees ; anon sans droit';
  DECLARE v_m1 text; v_m2 text; v_m3 text;
  BEGIN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_lect, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r1]); v_m1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_m1 := SQLERRM; END;
    EXECUTE 'RESET ROLE';
    UPDATE public.user_library_memberships SET role = 'librarian' WHERE user_id = v_lect AND library_id = v_lib;
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r1]); v_m2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_m2 := SQLERRM; END;
    EXECUTE 'RESET ROLE';
    UPDATE public.user_library_memberships SET role = 'reader' WHERE user_id = v_lect AND library_id = v_lib;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_preparer_mises_a_jour(v_run2, ARRAY[r1]); v_m3 := 'accepte';
    EXCEPTION WHEN OTHERS THEN v_m3 := SQLERRM; END;
    EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_m1 <> 'accepte' AND v_m2 LIKE 'Acesso restrito ao coordenador%' AND v_m3 LIKE 'Run % introuvable'
       AND NOT has_function_privilege('anon', 'public.fn_import_preparer_mises_a_jour(bigint, bigint[])', 'EXECUTE')
       AND NOT has_function_privilege('authenticated', 'ingest.fn_h21_preparer_exemplaires(bigint, bigint[], uuid, uuid, bigint)', 'EXECUTE')
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_m1, v_m2, v_m3)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T8 ──────────────────────────────────────────────────────────────
  v_t := 'T8 revision obligatoire ; rapport : prepared_item_updates, section H19 sans faux code pris';
  DECLARE v_h text; v_rap jsonb;
  BEGIN
    -- r3 : la note retouchée dans le brouillon AVANT la révision (règle (d))
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.exemplar_drafts SET notes = 'L6B note retouchee' WHERE id = d3;
    BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    v_res := public.fn_batch_review_request(v_lotX, NULL);
    v_rev := (v_res->>'review_id')::bigint;
    v_rap := public.fn_batch_review_report(v_lotX);
    IF v_h = 'error.publish.review_required'
       AND (v_rap->'prepared_item_updates'->>'count')::int = 4
       AND (v_rap->'prepared_item_updates'->>'applied_fields')::int = 4
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_rap->'prepared_item_updates'->'examples') x
                    WHERE (x->>'item_draft_id')::bigint = d1 AND (x->>'exemplar_id')::bigint = e1
                      AND x->'applied'->0->>'champ' = 'shelf_location' AND x->>'titulo' IS NOT NULL)
       AND coalesce((v_rap->'items'->>'code_taken')::int, 0) = 0
       AND coalesce((v_rap->'items'->>'count')::int, 0) = 0
       AND (v_rap->'prepared_updates'->>'count')::int = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : avant revision='||coalesce(v_h, '∅')
         ||' rapport='||left(coalesce((v_rap->'prepared_item_updates')::text, 'NULL'), 400)||' items='||coalesce((v_rap->'items')::text, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;
  -- (sans révision demandée — rien de préparé —, les tests suivants échouent, la suite continue)
  IF v_rev IS NOT NULL THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
    PERFORM public.fn_batch_review_verdict(v_rev, 'approved', NULL);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
  END IF;

  -- ── T9 ──────────────────────────────────────────────────────────────
  -- Chaque refus est essayé dans un sous-bloc annulé (sentinelle) : la
  -- perturbation ne reste pas.
  v_t := 'T9 refus a la publication : supprime (jamais une creation), change, deplace de notice, de fonds, bibliotheque, base, ligne, effet de bord, par le lot';
  DECLARE v_h text; v_hs text[] := ARRAY[]::text[]; v_hb bigint; v_cnt int;
  BEGIN
    -- (a) exemplaire supprimé : le lien tombe ; jamais une création
    BEGIN
      DELETE FROM public.exemplares WHERE id = e3;
      v_cnt := (SELECT count(*) FROM public.exemplares);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || (v_h || CASE WHEN (SELECT count(*) FROM public.exemplares) = v_cnt THEN '' ELSE '+CREATION' END);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (b) l'exemplaire a changé (étiquette)
    BEGIN
      UPDATE public.exemplares SET label_note = 'retouche' WHERE id = e1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (c) déplacé vers une autre notice (fonds de la notice du rang 2)
    BEGIN
      UPDATE public.exemplares SET holding_id = (SELECT h.id FROM public.book_holdings h WHERE h.book_id = b2 AND h.library_id = v_lib)
       WHERE id = e3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (d) la cible du brouillon : un autre fonds (celui d'une autre notice) —
    --     la publication y déplacerait l'exemplaire
    BEGIN
      UPDATE public.exemplar_drafts SET target_holding_id = (SELECT h.id FROM public.book_holdings h WHERE h.book_id = b2 AND h.library_id = v_lib)
       WHERE id = d3;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d3); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (e) la bibliothèque a changé (réattribuée à B)
    BEGIN
      INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (b1, v_libB, true) RETURNING id INTO v_hb;
      UPDATE public.exemplares SET library_id = v_libB, holding_id = v_hb WHERE id = e1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (f) la base a changé
    BEGIN
      UPDATE ingest.exemplar_import_baselines SET notes = 'autre base' WHERE exemplar_id = e1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (g) la ligne d'import n'est plus celle de la trace
    BEGIN
      UPDATE public.exemplar_drafts SET import_staging_row_id = r2 WHERE id = d1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (h) effet de bord : le tombo retouché dans le brouillon (par l'API)
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      UPDATE public.exemplar_drafts SET tombo = 'L6B-RETOUCHE-1' WHERE id = d1;
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (i) par le lot : un brouillon refusé fait refuser le lot entier
    BEGIN
      UPDATE public.exemplares SET label_note = 'retouche' WHERE id = e5;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_catalog_batch(v_lotX); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    -- (j) la cible du brouillon réattribuée à B (l'administration : la garde
    --     B29 de qui n'est pas staff de B ne joue pas)
    BEGIN
      UPDATE public.exemplar_drafts SET target_library_id = v_libB WHERE id = d1;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
      v_hs := v_hs || v_h;
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_hs = ARRAY['error.publish.item_update_gone', 'error.publish.item_update_changed', 'error.publish.item_update_moved',
                    'error.publish.item_update_moved', 'error.publish.item_update_library_changed',
                    'error.publish.item_update_baseline_changed', 'error.publish.item_update_import_row_gone',
                    'error.publish.item_update_side_effect', 'error.publish.item_update_changed',
                    'error.publish.item_update_library_changed']
       AND (SELECT status FROM public.exemplar_drafts WHERE id = d1) = 'draft'
       AND (SELECT shelf_location FROM public.exemplares WHERE id = e1) = 'JR SOU'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||array_to_string(v_hs, ' / ')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T10 ─────────────────────────────────────────────────────────────
  v_t := 'T10 la publication de la notice (publish_book_draft) ne publie pas le brouillon d''exemplaire du lot';
  BEGIN
    v_books := (SELECT string_agg(md5(to_jsonb(b)::text), ',' ORDER BY b.id) FROM public.books b WHERE b.id <> bN);
    EXECUTE 'SET LOCAL ROLE authenticated';
    PERFORM public.publish_book_draft(dNotice);
    EXECUTE 'RESET ROLE';
    IF (SELECT status FROM public.book_drafts WHERE id = dNotice) = 'published'
       AND (SELECT ano FROM public.books WHERE id = bN) = '1999'
       AND (SELECT status FROM public.exemplar_drafts WHERE id = dN) = 'draft'
       AND (SELECT notes FROM public.exemplares WHERE id = eN) = (SELECT bl.notes FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = eN)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : notice '||coalesce((SELECT status FROM public.book_drafts WHERE id = dNotice), '∅')
         ||' exemplaire '||coalesce((SELECT status FROM public.exemplar_drafts WHERE id = dN), '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T11 ─────────────────────────────────────────────────────────────
  v_t := 'T11 publication du lot : cote et note appliquees, TOUT LE RESTE INTACT (exemplaire, fonds, circulation, notices, identifiants) ; base selon (d)';
  DECLARE v_pub jsonb; v_pub3 jsonb;
  BEGIN
    v_extids := (SELECT string_agg(md5(to_jsonb(x)::text), ',' ORDER BY x.id) FROM public.book_external_ids x);
    -- la notice du rang 1 sans base : la publication de l'exemplaire n'en crée pas
    DELETE FROM ingest.book_import_baselines bl
     WHERE bl.external_id_id IN (SELECT i.id FROM public.book_external_ids i WHERE i.book_id = b1);
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_res := public.publish_catalog_batch(v_lotX);
    EXECUTE 'RESET ROLE';
    v_pub := (SELECT import_update->'publication' FROM public.exemplar_drafts WHERE id = d1);
    v_pub3 := (SELECT import_update->'publication' FROM public.exemplar_drafts WHERE id = d3);
    IF (v_res->>'exemplars_published')::int = 4
       AND (SELECT status FROM public.exemplar_drafts WHERE id = d1) = 'published'
       AND (SELECT shelf_location FROM public.exemplares WHERE id = e1) = 'JR SOU 2'
       AND (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = e1) = v_hp1
       AND (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = eN) = v_hpN
       AND (SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = e5) = v_hp5
       AND (SELECT shelf_location FROM public.exemplares WHERE id = e5) = 'JR CAU 5'
       AND (SELECT notes FROM public.exemplares WHERE id = e3) = 'L6B note retouchee'
       AND (SELECT notes FROM public.exemplares WHERE id = eN) LIKE '% (revue)'
       -- le fonds (comptes compris) et la circulation
       AND (SELECT md5((to_jsonb(h) - 'updated_at')::text) FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e1) = v_hold
       AND md5(concat_ws('|',
             (SELECT string_agg(md5(to_jsonb(i)::text), ',' ORDER BY i.id) FROM public.emprestimo_itens_v2 i WHERE i.item_id = e1),
             (SELECT string_agg(md5(to_jsonb(l)::text), ',' ORDER BY l.id) FROM public.reserva_linhas_v2 l WHERE l.item_id = e1),
             (SELECT string_agg(md5(to_jsonb(p)::text), ',' ORDER BY p.id) FROM public.emprestimos_v2 p WHERE p.id = v_emp))) = v_circ
       -- les notices (hors celle que le lot 4 a mise à jour) et les identifiants d'origine
       AND (SELECT string_agg(md5(to_jsonb(b)::text), ',' ORDER BY b.id) FROM public.books b WHERE b.id <> bN) = v_books
       AND (SELECT string_agg(md5(to_jsonb(x)::text), ',' ORDER BY x.id) FROM public.book_external_ids x) = v_extids
       -- l'exemplaire de B
       AND (SELECT md5(to_jsonb(e)::text) FROM public.exemplares e WHERE e.id = eB) = v_ebB
       -- la base : la cote avance (appliquée) ; la note retouchée garde B
       AND (SELECT bl.shelf_location = 'JR SOU 2' AND bl.run_id = v_run2 AND bl.staging_row_id = r1
              FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e1)
       AND v_pub->'avances' = '["shelf_location", "notes"]'::jsonb
       AND v_pub3->'avances' = '[]'::jsonb AND v_pub3->'gardes' = '["shelf_location", "notes"]'::jsonb
       AND (SELECT shelf_location FROM public.exemplares WHERE id = e3) = 'ER OPP LOCAL'
       AND (SELECT shelf_location FROM public.exemplares WHERE id = eN) = v_coteN
       AND (SELECT bl.notes IS NULL AND bl.run_id = v_run2 FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e3)
       AND (SELECT bl.notes LIKE '% (revue)' FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = eN)
       -- aucun exemplaire créé ; aucune base de notice créée (bloc H20)
       AND (SELECT count(*) FROM public.exemplares e WHERE e.import_run_id = v_run2) = 0
       AND NOT EXISTS (SELECT 1 FROM ingest.book_import_baselines bl
                        WHERE bl.external_id_id IN (SELECT i.id FROM public.book_external_ids i WHERE i.book_id = b1))
       -- l'empreinte de l'exemplaire tel que la publication l'a laissé
       AND (SELECT x.import_update->>'empreinte_apres' FROM public.exemplar_drafts x WHERE x.id = d1) = ingest.fn_h21_empreinte_exemplaire(e1)
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_res::text, 'NULL'), 200)
         ||' pub='||coalesce(v_pub::text, '∅')||' pub3='||coalesce(v_pub3::text, '∅')
         ||' e1='||coalesce((SELECT shelf_location FROM public.exemplares WHERE id = e1), '∅')
         ||' hp1='||((SELECT md5((to_jsonb(e) - array['shelf_location', 'notes', 'updated_at'])::text) FROM public.exemplares e WHERE e.id = e1) = v_hp1)::text
         ||' fonds='||(SELECT (to_jsonb(h) - 'updated_at')::text FROM public.exemplares e JOIN public.book_holdings h ON h.id = e.holding_id WHERE e.id = e1)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12 ─────────────────────────────────────────────────────────────
  v_t := 'T12 republication : retouche acceptee, base inchangee ; refusee si la bibliotheque ou la notice ont change';
  DECLARE v_h1 text; v_h2 text; v_hb bigint; v_bl text;
  BEGIN
    v_bl := (SELECT md5(to_jsonb(bl)::text) FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e1);
    EXECUTE 'SET LOCAL ROLE authenticated';
    UPDATE public.exemplar_drafts SET label_note = 'L6B etiquette' WHERE id = d1;
    PERFORM public.publish_exemplar_draft(d1);
    EXECUTE 'RESET ROLE';
    BEGIN
      INSERT INTO public.book_holdings (book_id, library_id, loanable) VALUES (b1, v_libB, true) RETURNING id INTO v_hb;
      UPDATE public.exemplares SET library_id = v_libB, holding_id = v_hb WHERE id = e1;
      PERFORM set_config('request.jwt.claims', json_build_object('sub', v_admin, 'role', 'authenticated')::text, true);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h1 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    BEGIN
      UPDATE public.exemplares SET holding_id = (SELECT h.id FROM public.book_holdings h WHERE h.book_id = b2 AND h.library_id = v_lib)
       WHERE id = e1;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h2 := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF (SELECT label_note FROM public.exemplares WHERE id = e1) = 'L6B etiquette'
       AND (SELECT shelf_location FROM public.exemplares WHERE id = e1) = 'JR SOU 2'
       AND (SELECT md5(to_jsonb(bl)::text) FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e1) = v_bl
       AND v_h1 = 'error.publish.item_update_library_changed' AND v_h2 = 'error.publish.item_update_moved'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE';
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T12b ────────────────────────────────────────────────────────────
  v_t := 'T12b un Editer publie apres la mise a jour : la republier est refuse, l''Editer reste intact';
  DECLARE v_h text; v_ed bigint; v_av jsonb; v_ap jsonb;
  BEGIN
    BEGIN
      EXECUTE 'SET LOCAL ROLE authenticated';
      v_ed := public.create_exemplar_draft_from_exemplar(e1, NULL);
      UPDATE public.exemplar_drafts SET shelf_location = 'L6B COTE EDITEE', label_note = 'L6B etiquette editee',
             visibility = 'staff_only', notes = 'L6B note editee' WHERE id = v_ed;
      PERFORM public.publish_exemplar_draft(v_ed);
      EXECUTE 'RESET ROLE';
      v_av := (SELECT to_jsonb(e) - 'updated_at' FROM public.exemplares e WHERE e.id = e1);
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM public.publish_exemplar_draft(d1); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_ap := (SELECT to_jsonb(e) - 'updated_at' FROM public.exemplares e WHERE e.id = e1);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_h = 'error.publish.item_update_changed_since_publication'
       AND v_ap = v_av AND v_ap->>'shelf_location' = 'L6B COTE EDITEE' AND v_ap->>'notes' = 'L6B note editee'
       AND v_ap->>'label_note' = 'L6B etiquette editee' AND v_ap->>'visibility' = 'staff_only'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_h, '∅')||' apres='||left(coalesce(v_ap::text, '∅'), 300)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T13 ─────────────────────────────────────────────────────────────
  v_t := 'T13 recalcul apres publication : cote appliquee inchangee, note retouchee en conflit (signal repete)';
  DECLARE v_l jsonb;
  BEGIN
    EXECUTE 'SET LOCAL ROLE authenticated';
    PERFORM public.fn_import_recomparer(v_run2, ARRAY[r1, r3]);
    SELECT jsonb_object_agg(l.id::text, l.exemplaires_maj) INTO v_l FROM public.fn_import_list_run_rows(v_run2) l WHERE l.id IN (r1, r3);
    EXECUTE 'RESET ROLE';
    IF v_l->(r1::text)->'items'->0->'verdicts' = '{"shelf_location": "inchange", "notes": "inchange"}'::jsonb
       AND v_l->(r3::text)->'items'->0->'verdicts' = '{"shelf_location": "local_seul", "notes": "conflit"}'::jsonb
       AND v_l->(r1::text)->'items'->0->>'draft_status' = 'published'
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce(v_l::text, 'NULL'), 500)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T14 ─────────────────────────────────────────────────────────────
  v_t := 'T14 une fusion de brouillons de notice n''emporte pas un brouillon de mise a jour d''exemplaire';
  DECLARE v_s bigint; v_l bigint; v_h text; v_x bigint; v_lot bigint;
  BEGIN
    BEGIN
      -- un lot ouvert de BLMF : deux brouillons de notice ; le perdant porte la
      -- référence que vise un brouillon de mise à jour d'exemplaire (préparé à
      -- nouveau, dans ce lot)
      INSERT INTO public.catalog_batches (name, created_by, library_id) VALUES ('L6B fusion', v_coord, v_lib) RETURNING id INTO v_lot;
      INSERT INTO public.book_drafts (batch_id, action, status, titulo, bib_ref, owner_library_id, created_by, updated_by)
      VALUES (v_lot, 'create', 'draft', 'L6B survivant', 'L6B-SURV', v_lib, v_coord, v_coord) RETURNING id INTO v_s;
      INSERT INTO public.book_drafts (batch_id, action, status, titulo, bib_ref, owner_library_id, created_by, updated_by)
      VALUES (v_lot, 'create', 'draft', 'L6B perdant', 'L6B-PERD', v_lib, v_coord, v_coord) RETURNING id INTO v_l;
      UPDATE public.exemplar_drafts SET batch_id = v_lot, target_bib_ref = 'L6B-PERD' WHERE id = d5;
      EXECUTE 'SET LOCAL ROLE authenticated';
      BEGIN PERFORM api.merge_book_drafts(v_s, v_l, '{}'::jsonb); v_h := 'accepte';
      EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h = PG_EXCEPTION_HINT; END;
      EXECUTE 'RESET ROLE';
      v_x := (SELECT CASE WHEN target_bib_ref = 'L6B-PERD' THEN 1 ELSE 0 END FROM public.exemplar_drafts WHERE id = d5);
      RAISE EXCEPTION 'sentinelle';
    EXCEPTION WHEN raise_exception THEN IF SQLERRM <> 'sentinelle' THEN RAISE; END IF; END;
    IF v_h = 'error.import.item_update_not_mergeable' AND v_x = 1
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||coalesce(v_h, '∅')); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T15 ─────────────────────────────────────────────────────────────
  v_t := 'T15 reprise des bases (idempotente) ; masquage des valeurs d''un exemplaire hors de vue';
  DECLARE v_n1 int; v_n2 int; v_lu jsonb; v_lm jsonb;
  BEGIN
    DELETE FROM ingest.exemplar_import_baselines WHERE exemplar_id IN (e4, e7);
    v_n1 := ingest.fn_h21_reprendre_les_bases_exemplaires();
    v_n2 := ingest.fn_h21_reprendre_les_bases_exemplaires();
    -- e1 réservé au staff : vu de la coordination de B, ses valeurs sont masquées
    UPDATE public.exemplares SET visibility = 'staff_only' WHERE id = e2b;
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coordB, 'role', 'authenticated')::text, true);
    v_lu := ingest.fn_h21_exemplaires_a_lire(ingest.fn_h21_exemplaires_trois_etats(r2));
    v_lm := ingest.fn_h21_exemplaires_maj(r2, ingest.fn_h21_exemplaires_trois_etats(r2), b2, false);
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    IF v_n1 = 3 AND v_n2 = 0   -- e4, e7 et e6 (base supprimée au décor)
       AND (SELECT bl.origine = 'reprise' AND bl.confirmed_at IS NULL AND bl.shelf_location = 'R ZIM' AND bl.run_id = v_run1
              FROM ingest.exemplar_import_baselines bl WHERE bl.exemplar_id = e4)
       AND (v_lu->'items'->1->>'a_masque')::boolean
       -- ni A, ni B, ni le verdict fin, ni base, ni applicables : « masque » et N
       AND v_lu->'items'->1->'champs'->0 = '{"champ": "shelf_location", "verdict": "masque", "n": "R HER N"}'::jsonb
       AND NOT (v_lu->'items'->1 ? 'baseline_id') AND NOT (v_lu->'items'->1 ? 'applicables')
       AND v_lm->'items'->1->'verdicts' = '{"shelf_location": "masque", "notes": "masque"}'::jsonb
       AND (v_lm->'items'->1->>'applicables')::int = 0
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : reprises '||v_n1||'/'||v_n2||' lu='||left(coalesce(v_lu::text, 'NULL'), 400)); END IF;
  EXCEPTION WHEN OTHERS THEN
    PERFORM set_config('request.jwt.claims', json_build_object('sub', v_coord, 'role', 'authenticated')::text, true);
    v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T16 ─────────────────────────────────────────────────────────────
  v_t := 'T16 structure et droits : table fermee (RLS sans politique, aucun droit API), aides fermees, portes authenticated seulement';
  BEGIN
    IF (SELECT c.relrowsecurity FROM pg_class c WHERE c.oid = 'ingest.exemplar_import_baselines'::regclass)
       AND NOT EXISTS (SELECT 1 FROM pg_policy p WHERE p.polrelid = 'ingest.exemplar_import_baselines'::regclass)
       AND NOT has_table_privilege('authenticated', 'ingest.exemplar_import_baselines', 'SELECT')
       AND NOT has_table_privilege('anon', 'ingest.exemplar_import_baselines', 'SELECT')
       AND NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
                        WHERE n.nspname = 'ingest'
                          AND p.proname IN ('fn_h21_champs_exemplaire', 'fn_h21_n_exemplaire', 'fn_h21_item_de_la_ligne',
                                            'fn_h21_empreinte_exemplaire', 'fn_h21_empreinte_hors_patch',
                                            'fn_h21_empreinte_base_exemplaire', 'fn_h21_exemplaire_visible',
                                            'fn_h21_poser_base_exemplaire', 'fn_h21_reprendre_les_bases_exemplaires',
                                            'fn_h21_exemplaires_trois_etats', 'fn_h21_stocker_comparaisons_exemplaires',
                                            'fn_h21_exemplaires_maj', 'fn_h21_exemplaires_a_lire', 'fn_h21_preparer_exemplaires',
                                            'fn_h21_garde_mise_a_jour_exemplaire', 'fn_h21_avancer_base_exemplaire')
                          AND (has_function_privilege('authenticated', p.oid, 'EXECUTE') OR has_function_privilege('anon', p.oid, 'EXECUTE')))
       AND (SELECT count(*) FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
             WHERE n.nspname = 'ingest' AND p.proname LIKE 'fn_h21_%exemplaire%') >= 10
       AND NOT has_function_privilege('anon', 'public.fn_import_row_comparison(bigint, bigint)', 'EXECUTE')
       AND NOT has_function_privilege('anon', 'public.fn_import_list_run_rows(bigint)', 'EXECUTE')
       AND NOT has_function_privilege('anon', 'public.publish_exemplar_draft(bigint)', 'EXECUTE')
       AND has_function_privilege('authenticated', 'public.fn_import_list_run_rows(bigint)', 'EXECUTE')
       AND EXISTS (SELECT 1 FROM pg_index i WHERE i.indrelid = 'ingest.exemplar_import_baselines'::regclass AND i.indisunique
                    AND i.indkey[0] = (SELECT a.attnum FROM pg_attribute a WHERE a.attrelid = 'ingest.exemplar_import_baselines'::regclass AND a.attname = 'exemplar_id'))
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t); END IF;
  EXCEPTION WHEN OTHERS THEN v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18 ─────────────────────────────────────────────────────────────
  v_t := 'T18 mesure : une page de 200 lignes recalculee puis preparee (200 brouillons d''exemplaire), coordination, < 8 s chacune';
  DECLARE v_rows bigint[]; v_ms2 numeric; v_h bigint;
  BEGIN
    v_h := (SELECT e.holding_id FROM public.exemplares e WHERE e.id = e10);
    INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, shelf_location, source_item_code, source_item_id, import_source_id, import_run_id, circulation_policy)
    SELECT e.bib_ref, 'L6B-M-' || g, v_lib, v_h, 'M ' || g, 'L6BM-' || g, 'M' || g, v_src, v_run1, e.circulation_policy
      FROM public.exemplares e CROSS JOIN generate_series(1, 200) g WHERE e.id = e10;
    INSERT INTO ingest.exemplar_import_baselines (exemplar_id, library_id, source_id, run_id, source_item_code, source_item_id, shelf_location, payload_hash, origine, confirmed_at)
    SELECT e.id, v_lib, v_src, v_run1, e.source_item_code, e.source_item_id, e.shelf_location, md5(e.id::text), 'import', now()
      FROM public.exemplares e WHERE e.tombo LIKE 'L6B-M-%';
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6b-mesure.iso', 'l6b-mesure.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_runM;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    SELECT v_runM, g, (SELECT sr.external_key FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r10), 'L6B Mesure ' || g,
           -- (la ligne 200 décrit l'exemplaire de la ligne 1 : un seul brouillon)
           jsonb_build_object('items', jsonb_build_array(jsonb_build_object('source_item_code', 'L6BM-' || CASE WHEN g = 200 THEN 1 ELSE g END,
                                                                            'source_item_id', 'M' || CASE WHEN g = 200 THEN 1 ELSE g END,
                                                                            'call_number', 'M ' || CASE WHEN g = 200 THEN 1 ELSE g END || ' bis'))),
           'known_record', 'pending', (SELECT h.book_id FROM public.book_holdings h WHERE h.id = v_h)
      FROM generate_series(1, 200) g;
    v_rows := ARRAY(SELECT id FROM ingest.partner_catalog_staging_rows WHERE run_id = v_runM ORDER BY id);
    ANALYZE public.exemplares, public.exemplar_drafts, ingest.exemplar_import_baselines, ingest.partner_catalog_staging_rows;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_t0 := clock_timestamp();
    v_res := public.fn_import_recomparer(v_runM, v_rows);
    v_ms := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    v_t0 := clock_timestamp();
    v_res2 := public.fn_import_preparer_mises_a_jour(v_runM, v_rows);
    v_ms2 := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    EXECUTE 'RESET ROLE';
    RAISE NOTICE 'H21L6B-MESURE recalcul 200 lignes : % ms ; preparer 200 lignes (200 brouillons d''exemplaire) : % ms', round(v_ms), round(v_ms2);
    IF (v_res->>'exemplaires_comparees')::int = 200 AND (v_res2->'exemplaires'->>'prepared')::int = 199
       AND v_res2->'exemplaires'->'skipped' = '{"deja_preparee": 1}'::jsonb
       AND v_ms < 8000 AND v_ms2 < 8000
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||left(coalesce((v_res2->'exemplaires' - 'drafts')::text, 'NULL'), 300)
         ||' ; '||round(v_ms)||' ms / '||round(v_ms2)||' ms'); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18b ────────────────────────────────────────────────────────────
  v_t := 'T18b mesure : 200 lignes x 25 exemplaires (5 000 brouillons), recalcul et preparation < 8 s chacun';
  DECLARE v_runP bigint; v_rowsP bigint[]; v_hP bigint; v_ms2 numeric;
  BEGIN
    v_hP := (SELECT e.holding_id FROM public.exemplares e WHERE e.id = e9);
    INSERT INTO public.exemplares (bib_ref, tombo, library_id, holding_id, shelf_location, notes, source_item_code, source_item_id, import_source_id, import_run_id, circulation_policy)
    SELECT e.bib_ref, 'L6B-P-' || g || '-' || i, v_lib, v_hP, 'P ' || g || '-' || i, 'note ' || i, 'L6BP-' || g || '-' || i, 'P' || g || '-' || i, v_src, v_run1, e.circulation_policy
      FROM public.exemplares e CROSS JOIN generate_series(1, 200) g CROSS JOIN generate_series(1, 25) i WHERE e.id = e9;
    INSERT INTO ingest.exemplar_import_baselines (exemplar_id, library_id, source_id, run_id, source_item_code, source_item_id, shelf_location, notes, payload_hash, origine, confirmed_at)
    SELECT e.id, v_lib, v_src, v_run1, e.source_item_code, e.source_item_id, e.shelf_location, e.notes, md5(e.id::text), 'import', now()
      FROM public.exemplares e WHERE e.tombo LIKE 'L6B-P-%';
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6b-mesure25.iso', 'l6b-mesure25.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_runP;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    SELECT v_runP, g, (SELECT sr.external_key FROM ingest.partner_catalog_staging_rows sr WHERE sr.id = r9), 'L6B Mesure25 ' || g,
           jsonb_build_object('items', (SELECT jsonb_agg(jsonb_build_object('source_item_code', 'L6BP-' || g || '-' || i, 'source_item_id', 'P' || g || '-' || i,
                                                                           'call_number', 'P ' || g || '-' || i || ' bis', 'note', 'note ' || i || ' bis')) FROM generate_series(1, 25) i)),
           'known_record', 'pending', (SELECT h.book_id FROM public.book_holdings h WHERE h.id = v_hP)
      FROM generate_series(1, 200) g;
    v_rowsP := ARRAY(SELECT id FROM ingest.partner_catalog_staging_rows WHERE run_id = v_runP ORDER BY id);
    ANALYZE public.exemplares, public.exemplar_drafts, ingest.exemplar_import_baselines, ingest.partner_catalog_staging_rows;
    EXECUTE 'SET LOCAL ROLE authenticated';
    v_t0 := clock_timestamp();
    v_res := public.fn_import_recomparer(v_runP, v_rowsP);
    v_ms := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    v_t0 := clock_timestamp();
    v_res2 := public.fn_import_preparer_mises_a_jour(v_runP, v_rowsP);
    v_ms2 := extract(epoch FROM clock_timestamp() - v_t0) * 1000;
    EXECUTE 'RESET ROLE';
    RAISE NOTICE 'H21L6B-MESURE 200 lignes x 25 exemplaires : recalcul % ms ; preparer % ms (% brouillons d''exemplaire)', round(v_ms), round(v_ms2), v_res2->'exemplaires'->'prepared';
    IF (v_res2->'exemplaires'->>'prepared')::int = 5000 AND v_res2->'exemplaires'->'skipped' = '{}'::jsonb
       AND v_ms < 8000 AND v_ms2 < 8000
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1;
      v_failures := v_failures || (v_t || ' : ' || coalesce(((v_res2->'exemplaires') - 'drafts')::text, 'NULL')
                                   || ' ; ' || round(v_ms)::text || ' ms / ' || round(v_ms2)::text || ' ms'); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  -- ── T18c ────────────────────────────────────────────────────────────
  v_t := 'T18c au-dela de 5 000 exemplaires du fichier par appel : recalcul et preparation refuses (HINT), rien d''ecrit';
  DECLARE v_runQ bigint; v_rowQ bigint; v_h1 text; v_h2 text;
  BEGIN
    INSERT INTO ingest.partner_catalog_import_runs (source_id, library_id, storage_path, original_filename, detected_format, run_status)
    VALUES (v_src, v_lib, 'essai/l6b-plafond.iso', 'l6b-plafond.iso', 'marc_iso2709', 'ready_for_review') RETURNING id INTO v_runQ;
    INSERT INTO ingest.partner_catalog_staging_rows (run_id, row_no, external_key, title, normalized_payload, match_status, editorial_decision, proposed_book_id)
    VALUES (v_runQ, 1, 'L6B-PLAFOND', 'L6B Plafond',
            jsonb_build_object('items', (SELECT jsonb_agg(jsonb_build_object('source_item_code', 'L6BQ-' || i, 'call_number', 'Q ' || i))
                                           FROM generate_series(1, 5001) i)),
            'known_record', 'pending', b1)
    RETURNING id INTO v_rowQ;
    EXECUTE 'SET LOCAL ROLE authenticated';
    BEGIN PERFORM public.fn_import_recomparer(v_runQ, ARRAY[v_rowQ]); v_h1 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h1 = PG_EXCEPTION_HINT; END;
    BEGIN PERFORM public.fn_import_preparer_mises_a_jour(v_runQ, ARRAY[v_rowQ]); v_h2 := 'accepte';
    EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS v_h2 = PG_EXCEPTION_HINT; END;
    EXECUTE 'RESET ROLE';
    IF v_h1 = 'error.import.update_page_too_many_items' AND v_h2 = 'error.import.update_page_too_many_items'
       AND (SELECT exemplaires_comparaison IS NULL AND comparaison IS NULL FROM ingest.partner_catalog_staging_rows WHERE id = v_rowQ)
       AND ingest.fn_h21_exemplaires_par_appel() = 5000
    THEN v_passed := v_passed+1;
    ELSE v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||concat_ws(' / ', v_h1, v_h2)); END IF;
  EXCEPTION WHEN OTHERS THEN EXECUTE 'RESET ROLE'; v_failed := v_failed+1; v_failures := v_failures||(v_t||' : '||SQLERRM); END;

  IF v_failed = 0 THEN
    RAISE EXCEPTION 'H21-LOT6B-EXEMPLAIRES-MAJ OK : %/% tests passés', v_passed, v_passed;
  ELSE
    RAISE EXCEPTION 'H21-LOT6B-EXEMPLAIRES-MAJ ECHEC : %/% OK, % échec(s) | %', v_passed, v_passed + v_failed, v_failed, array_to_string(v_failures, ' || ');
  END IF;
END $$;
